<script setup lang="ts">
import {ref,reactive,computed,onMounted,watch,onBeforeUnmount} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {ElMessage,type FormInstance} from 'element-plus'
import {Crop,DataAnalysis,ChatDotRound,Box,Location,UserFilled,SwitchButton,Collection,Setting,Sunny,Document,Menu,Close} from '@element-plus/icons-vue'
import {api,post,token,type User,type ModuleSpec} from './api'
import Dashboard from './views/Dashboard.vue'
import Records from './views/Records.vue'
import Inventory from './views/Inventory.vue'
import AIAssistant from './views/AIAssistant.vue'
import Knowledge from './views/Knowledge.vue'
import Crops from './views/Crops.vue'
import FarmMap from './views/FarmMap.vue'
import Admin from './views/Admin.vue'
import Weather from './views/Weather.vue'
import Files from './views/Files.vue'
import PlantingFlow from './views/PlantingFlow.vue'
import DefenseWorkbench from './views/DefenseWorkbench.vue'
import PublicTrace from './views/PublicTrace.vue'
const defenseSections=['timeline','environment-rules','finance','harvest-trace','guides','market-analysis','notifications','reports','account']
const router=useRouter(),route=useRoute(),user=ref<User>(),modules=ref<ModuleSpec[]>([]),initializing=ref(true),loginBusy=ref(false),loginError=ref(''),loginForm=ref<FormInstance>(),health=ref<{database:string;redis:boolean;model_configured:boolean;model:string;weather:string}>(),aiCrop=ref('')
const credentials=reactive({username:'farmer',password:''}),demoRole=ref('farmer')
const mobileMenu=ref(false)
watch(()=>route.fullPath,()=>{mobileMenu.value=false})
watch(mobileMenu,open=>{document.body.style.overflow=open?'hidden':''})
function closeMenu(event:KeyboardEvent){if(event.key==='Escape')mobileMenu.value=false}
function resizeMenu(){if(window.innerWidth>760)mobileMenu.value=false}
onMounted(()=>{window.addEventListener('keydown',closeMenu);window.addEventListener('resize',resizeMenu)})
onBeforeUnmount(()=>{window.removeEventListener('keydown',closeMenu);window.removeEventListener('resize',resizeMenu);document.body.style.overflow=''})
const roleNames={farmer:'合作社 / 种植大户',regulator:'乡镇农业监管员',admin:'系统管理员'}
const section=computed(()=>route.path.split('/')[2]||'dashboard'),spec=computed(()=>modules.value.find(m=>m.id===section.value))
const grouped=computed(()=>{const map=new Map<string,ModuleSpec[]>();for(const m of modules.value){if(!map.has(m.group))map.set(m.group,[]);map.get(m.group)!.push(m)}return [...map.entries()]})
const emptyMapSpec:ModuleSpec={id:'lands',title:'GIS 地块',group:'辖区监管',fields:[],roles:[],note:''}
const extraPages:Record<string,{title:string;text:string}>={reports:{title:'经营与农情报表',text:'各业务模块可导出台账；PDF 可通过浏览器打印生成。专业成本分摊、多年对比和预测评测尚未实现，当前看板只统计已有记录。'},backup:{title:'备份与恢复管理',text:'当前提供数据库备份操作说明，不在页面执行高风险恢复。可使用 MySQL 工具备份 nongzhixing；恢复前先备份现有数据。自动备份任务尚未配置。'},notifications:{title:'消息与待办中心',text:'告警模块与农事任务已保存至数据库；独立消息订阅和推送中心待扩展。'},files:{title:'附件管理',text:'上传、下载与访问权限由后端管理，附件按当前经营主体隔离。'}}
async function bootstrap(){modules.value=await api<ModuleSpec[]>('/modules');health.value=await api('/health')}
async function login(){if(!await loginForm.value?.validate().catch(()=>false))return;loginBusy.value=true;loginError.value='';try{const r=await post<{token:string;user:User}>('/auth/login',credentials);sessionStorage.setItem('nx-token',r.token);user.value=r.user;credentials.password='';await bootstrap();await router.push('/workspace/dashboard');ElMessage.success('登录成功')}catch(e){loginError.value=(e as Error).message;sessionStorage.removeItem('nx-token');user.value=undefined}finally{loginBusy.value=false}}
function navigate(id:string){mobileMenu.value=false;router.push('/workspace/'+id)}
function logout(){sessionStorage.removeItem('nx-token');user.value=undefined;modules.value=[];credentials.password='';router.push('/login')}
function askCrop(name:string){aiCrop.value=name;navigate('ai')}
function printPage(){window.print()}
onMounted(async()=>{if(route.path.startsWith('/trace/')){initializing.value=false;return}window.addEventListener('nx-unauthorized',logout);try{if(token()){user.value=await api<User>('/auth/me');await bootstrap();if(!route.path.startsWith('/workspace'))navigate('dashboard')}}catch{logout()}finally{initializing.value=false}})
</script>
<template><PublicTrace v-if="route.path.startsWith('/trace/')"/><div v-else-if="initializing" class="empty">正在连接农知行…</div>
<div v-else-if="!user" class="login-page"><div class="login-story"><div class="brand"><span class="brand-mark"><el-icon size="25"><Crop/></el-icon></span><div>农知行<small>NONGZHIXING</small></div></div><el-tag type="success" style="margin-top:30px">智能管理惠农平台 · PC / 手机</el-tag><h1>种得有依据，<br/>卖得有参考。</h1><p>连接生长、环境与市场。用完整的生产记录和可审核的智能建议，辅助科学种植与产销协同。</p><div class="tags" style="margin-top:26px"><el-tag>全周期种植</el-tag><el-tag>病虫害初筛</el-tag><el-tag>市场与产销</el-tag></div></div>
<section class="login-card"><h2>登录农业工作台</h2><el-select v-model="demoRole" @change="credentials.username=demoRole" style="width:100%;margin-top:20px"><el-option v-for="(label,key) in roleNames" :key="key" :label="label" :value="key"/></el-select><el-form ref="loginForm" :model="credentials" label-position="top" @submit.prevent="login"><el-form-item label="账号" prop="username" :rules="[{required:true,message:'请填写账号',trigger:'blur'}]"><el-input v-model="credentials.username" placeholder="填写账号" autocomplete="username"/></el-form-item><el-form-item label="密码" prop="password" :rules="[{required:true,message:'请填写密码',trigger:'blur'}]"><el-input v-model="credentials.password" placeholder="填写账号密码" type="password" show-password autocomplete="current-password" @keyup.enter="login"/></el-form-item><el-alert v-if="loginError" :title="loginError" type="error" :closable="false" style="margin-bottom:18px"/><el-button type="primary" :loading="loginBusy" @click="login" style="width:100%;height:44px">登录工作台</el-button></el-form></section></div>
<div v-else class="app-shell"><button v-if="mobileMenu" class="menu-backdrop" aria-label="关闭导航菜单" @click="mobileMenu=false"></button><aside id="workspace-navigation" class="sidebar" :class="{'is-open':mobileMenu}"><button class="menu-close" aria-label="关闭导航菜单" @click="mobileMenu=false"><el-icon><Close/></el-icon></button><div class="brand"><span class="brand-mark"><el-icon><Crop/></el-icon></span><div>农知行<small>智慧农业惠农平台</small></div></div><el-menu :default-active="section" @select="navigate" :default-openeds="['work']"><el-menu-item index="dashboard"><el-icon><DataAnalysis/></el-icon><span>数据看板</span></el-menu-item><el-menu-item v-if="user.role==='farmer'" index="planting-flow"><el-icon><Crop/></el-icon><span>种植管理流程</span></el-menu-item><el-sub-menu v-if="user.role==='farmer'" index="production-tools"><template #title><el-icon><Crop/></el-icon><span>生产与经营分析</span></template><el-menu-item index="timeline">地块生长时间轴</el-menu-item><el-menu-item index="environment-rules">环境阈值与预警</el-menu-item><el-menu-item index="finance">成本与销售收益</el-menu-item><el-menu-item index="harvest-trace">采收与产品溯源</el-menu-item><el-menu-item index="market-analysis">市场行情与销售参考</el-menu-item></el-sub-menu><el-menu-item index="guides">农技种植资料</el-menu-item><el-menu-item index="notifications">消息与待办</el-menu-item><el-menu-item index="ai"><el-icon><ChatDotRound/></el-icon><span>农业智能助手</span></el-menu-item><el-menu-item v-if="user.role==='farmer'" index="crops"><el-icon><Collection/></el-icon><span>作物与种植方案</span></el-menu-item><el-sub-menu v-for="[group,items] in grouped" :key="group" :index="group"><template #title><el-icon><Document/></el-icon><span>{{group}}</span></template><el-menu-item v-for="m in items" :key="m.id" :index="m.id">{{m.title}}</el-menu-item></el-sub-menu><el-sub-menu index="work"><template #title><el-icon><Setting/></el-icon><span>工作工具</span></template><el-menu-item v-if="user.role!=='admin'" index="inventory">库存与销售订单</el-menu-item><el-menu-item v-if="user.role==='regulator'" index="region-map">辖区 GIS 一张图</el-menu-item><el-menu-item v-if="user.role==='admin'" index="users">用户与权限</el-menu-item><el-menu-item v-if="user.role==='admin'" index="audit">操作日志审计</el-menu-item><el-menu-item v-if="user.role==='admin'" index="backup">备份与恢复说明</el-menu-item><el-menu-item v-if="user.role!=='admin'" index="weather">天气中心</el-menu-item><el-menu-item index="reports">统计与报表</el-menu-item><el-menu-item index="files">附件管理</el-menu-item><el-menu-item index="account">修改账号密码</el-menu-item></el-sub-menu></el-menu><div class="sidebar-note">{{roleNames[user.role]}}<br/>数据范围：{{user.role==='regulator'?user.district:user.org}}</div></aside>
<div class="workspace-body"><header class="topbar"><button class="menu-toggle" aria-label="打开导航菜单" aria-controls="workspace-navigation" :aria-expanded="mobileMenu" @click="mobileMenu=!mobileMenu"><el-icon><Menu/></el-icon></button><div class="topbar-heading"><div class="topbar-title">{{user.org}}</div><div class="muted">科学种植 · 规范记录 · 产销协同</div></div><div class="flex topbar-status"><el-tag :type="health?.redis?'success':'warning'">Redis {{health?.redis?'在线':'不可用'}}</el-tag><el-tag type="info">{{health?.database}}</el-tag><span class="muted">{{user.name}}</span><el-button text @click="logout"><el-icon><SwitchButton/></el-icon>退出登录</el-button></div></header>
<main class="main"><Dashboard v-if="section==='dashboard'" :user="user" :modules="modules" @navigate="navigate"/><PlantingFlow v-else-if="section==='planting-flow'&&user.role==='farmer'" :user="user"/><AIAssistant v-else-if="section==='ai'" :user="user" :initial-crop="aiCrop"/><Knowledge v-else-if="section==='knowledge'" :user="user"/><Crops v-else-if="section==='crops'&&user.role==='farmer'" @ask="askCrop"/><Inventory v-else-if="section==='inventory'&&user.role!=='admin'" :user="user"/><FarmMap v-else-if="section==='lands'&&spec" :spec="spec"/><FarmMap v-else-if="section==='region-map'&&user.role==='regulator'" :spec="emptyMapSpec" readonly/><Admin v-else-if="['users','audit'].includes(section)&&user.role==='admin'" :section="section"/><Weather v-else-if="section==='weather'"/><DefenseWorkbench :key="section" v-else-if="defenseSections.includes(section)&&(user.role==='farmer'||['guides','notifications','reports','account'].includes(section))" :section="section" :user="user" :modules="modules"/><Records v-else-if="spec" :key="spec.id" :spec="spec"/><Files v-else-if="section==='files'"/><section v-else-if="extraPages[section]" class="panel"><h2>{{extraPages[section].title}}</h2><el-alert :title="extraPages[section].text" type="info" :closable="false"/><el-button @click="navigate('dashboard')" style="margin-top:20px">返回看板</el-button><el-button @click="printPage" style="margin:20px 0 0 10px">打印当前页面 / 保存 PDF</el-button></section><el-empty v-else description="页面不存在或没有权限"/><div class="footer-note">农知行 · 用户录入与演示样本分开标注 · AI 建议需人工确认</div></main><nav class="mobile-nav" aria-label="常用导航"><button :class="{active:section==='dashboard'}" @click="navigate('dashboard')"><el-icon><DataAnalysis/></el-icon>看板</button><button :class="{active:section===(user.role==='farmer'?'planting-flow':'notifications')}" @click="navigate(user.role==='farmer'?'planting-flow':'notifications')"><el-icon><Crop/></el-icon>{{user.role==='farmer'?'种植':'待办'}}</button><button :class="{active:section==='ai'}" @click="navigate('ai')"><el-icon><ChatDotRound/></el-icon>智能助手</button><button :class="{active:mobileMenu}" :aria-expanded="mobileMenu" @click="mobileMenu=!mobileMenu"><el-icon><Menu/></el-icon>全部功能</button></nav></div></div>
</template>


